using System.Diagnostics;
using System.Net;
using System.Net.Http;
using System.Text.Json;
using Microsoft.Win32;
namespace LeoLauncher;
sealed record MusicSong(string Id,string Mid,string Name,string Artist,string Album="");
sealed class MusicHistory
{
    readonly string? path;public List<MusicSong> Items{get;private set;}=[];
    bool blocked;
    public MusicHistory(string? file){path=file;try{if(file!=null&&(File.Exists(file)||File.Exists(file+".bak")))Items=AtomicJson.Read(file,text=>(JsonSerializer.Deserialize<List<MusicSong>>(text)??throw new IOException("最近点歌为空")).Where(QQMusic.Valid).DistinctBy(s=>s.Id).Take(10).ToList());}catch{blocked=true;}}
    public void Add(MusicSong song){if(blocked)throw new IOException("最近点歌文件无法读取，原文件已保留");if(!QQMusic.Valid(song))throw new ArgumentException("歌曲无效");var next=Items.Where(s=>s.Id!=song.Id).Prepend(song).Take(10).ToList();if(path!=null)AtomicJson.Write(path,JsonSerializer.Serialize(next));Items=next;}

}
static class QQMusic
{
    static readonly HttpClient http=new(new HttpClientHandler{AllowAutoRedirect=false,UseCookies=false}){Timeout=TimeSpan.FromSeconds(12)};
    public static bool Valid(MusicSong s)=>s!=null&&s.Id is {Length:>0 and <=18}&&s.Id.All(char.IsAsciiDigit)&&s.Mid is {Length:>0 and <40}&&s.Mid.All(char.IsAsciiLetterOrDigit)&&s.Name is {Length:>0 and <=300}&&s.Artist is {Length:<=1000}&&s.Album is {Length:<=1000};
    static string Clean(string text)=>WebUtility.HtmlDecode(System.Text.RegularExpressions.Regex.Replace(text,"<[^>]*>",""));
    static string Str(JsonElement e,string key)=>e.TryGetProperty(key,out var v)?v.ValueKind==JsonValueKind.String?v.GetString()??"":v.ToString():"";
    public static MusicSong[] Parse(string json){using var doc=JsonDocument.Parse(json);var r=doc.RootElement;if(r.TryGetProperty("code",out var code)&&code.GetInt32()!=0)throw new InvalidOperationException("QQ音乐暂未返回搜索结果");if(!r.TryGetProperty("data",out var data)||!data.TryGetProperty("song",out var section))return [];var list=section.TryGetProperty("list",out var old)?old:section.TryGetProperty("itemlist",out var quick)?quick:default;if(list.ValueKind!=JsonValueKind.Array)return [];return list.EnumerateArray().Select(s=>{bool normal=s.TryGetProperty("songid",out _);string artist=normal&&s.TryGetProperty("singer",out var a)&&a.ValueKind==JsonValueKind.Array?string.Join(" / ",a.EnumerateArray().Select(x=>Str(x,"name"))):Str(s,"singer");return new MusicSong(Str(s,normal?"songid":"id"),Str(s,normal?"songmid":"mid"),Clean(Str(s,normal?"songname":"name")),Clean(artist),Clean(Str(s,"albumname")));}).Where(Valid).DistinctBy(s=>s.Id).Take(8).ToArray();}
    public static async Task<MusicSong[]> Search(string query,CancellationToken token){query=query.Trim();if(query.Length<1||query.Length>120)throw new ArgumentException("请输入1至120个字的歌名或歌手");string key=Uri.EscapeDataString(query);Exception? failure=null;foreach(var url in new[]{"https://c.y.qq.com/soso/fcgi-bin/client_search_cp?w="+key+"&format=json&p=1&n=8","https://c.y.qq.com/splcloud/fcgi-bin/smartbox_new.fcg?key="+key+"&format=json&inCharset=utf8&outCharset=utf-8"}){token.ThrowIfCancellationRequested();try{using var request=new HttpRequestMessage(HttpMethod.Get,url);request.Headers.Referrer=new Uri("https://y.qq.com/");request.Headers.UserAgent.ParseAdd("Mozilla/5.0");using var response=await http.SendAsync(request,token);response.EnsureSuccessStatusCode();var songs=Parse(await response.Content.ReadAsStringAsync(token));if(songs.Length>0)return songs;}catch(Exception e)when(e is HttpRequestException or JsonException or InvalidOperationException or TaskCanceledException){token.ThrowIfCancellationRequested();failure=e;}}if(failure!=null)throw new InvalidOperationException("QQ音乐搜索暂不可用，可打开客户端搜索");return [];}
    public static string? ClientPath(){var selected=ModulePaths.Selected("music");if(selected!=null)return selected;foreach(var process in Process.GetProcessesByName("QQMusic")){using(process)try{string? path=process.MainModule?.FileName;if(IsClient(path))return path;}catch{}}foreach(var hive in new[]{RegistryHive.CurrentUser,RegistryHive.LocalMachine})foreach(var view in new[]{RegistryView.Registry64,RegistryView.Registry32})try{using var root=RegistryKey.OpenBaseKey(hive,view);using var key=root.OpenSubKey(@"SOFTWARE\Microsoft\Windows\CurrentVersion\App Paths\QQMusic.exe");string? path=key?.GetValue("") as string;if(IsClient(path))return path;}catch{}try{using var key=Registry.ClassesRoot.OpenSubKey(@"QQMusic.qmc0\Shell\open\Command");string value=key?.GetValue("") as string??"";var m=System.Text.RegularExpressions.Regex.Match(value,"^\\\"([^\\\"]+QQMusic\\.exe)\\\"",System.Text.RegularExpressions.RegexOptions.IgnoreCase);if(m.Success&&IsClient(m.Groups[1].Value))return m.Groups[1].Value;}catch{}foreach(var drive in DriveInfo.GetDrives().Where(d=>d.DriveType==DriveType.Fixed))foreach(var folder in new[]{"Program Files (x86)","Program Files"}){string path=Path.Combine(drive.Name,folder,"Tencent","QQMusic","QQMusic.exe");if(IsClient(path))return path;}return null;}
    static bool IsClient(string? path)=>path!=null&&File.Exists(path)&&Path.GetFileName(path).Equals("QQMusic.exe",StringComparison.OrdinalIgnoreCase);
    public static void OpenClient(CancellationToken token=default){string path=ClientPath()??throw new InvalidOperationException("未找到QQ音乐，请先安装或打开客户端");token.ThrowIfCancellationRequested();using var process=Process.Start(new ProcessStartInfo(path){UseShellExecute=true});}
    public static string SongUrl(MusicSong song){if(!Valid(song))throw new ArgumentException("歌曲无效");return "https://y.qq.com/n/ryqq/songDetail/"+song.Mid;}
}
